import ast,base64,hashlib,json
source=base64.b64decode('',validate=True)
before=base64.b64decode('',validate=True)
tree=ast.parse(source,filename='mac_complete_source_append_inert_r3.py')
prior=ast.parse(before,filename='r2_actual_source.py')
compile(tree,'mac_complete_source_append_inert_r3.py','exec')
compile(prior,'r2_actual_source.py','exec')
def values(t):
    return {n.targets[0].id:ast.literal_eval(n.value) for n in t.body
            if isinstance(n,ast.Assign) and len(n.targets)==1 and isinstance(n.targets[0],ast.Name)
            and n.targets[0].id in ('PINS','PRESERVED','DOCUMENTS','NEW_NAMES','PAYLOAD_BYTES','PAYLOAD_SHA','ANCHOR_SHA')}
v=values(tree)
assert len(v['PINS'])==18 and len(v['NEW_NAMES'])==len(set(v['NEW_NAMES']))==12
assert set(v['PRESERVED'])==set(v['PINS'])-set(v['NEW_NAMES']) and len(v['PRESERVED'])==6
assert len(v['DOCUMENTS'])==3 and len(v['NEW_NAMES'])+len(v['DOCUMENTS'])==15
assert sum(k.endswith('.py') for k in v['PINS'])==14
assert sum(k.endswith('.mjs') for k in v['PINS'])==4
assert all(len(x)==9 and all(isinstance(y,str) and y.isdecimal() for y in x) for x in v['PRESERVED'].values())
assert v['PAYLOAD_BYTES']==513624 and v['PAYLOAD_SHA']=='f819276fa24fc5f4d7136ccb7f382db3897bea82aea6ee25172d5edce0f7163a'
def segment(raw,t,name):
    node=next(n for n in t.body if isinstance(n,(ast.FunctionDef,ast.ClassDef)) and n.name==name)
    return ast.get_source_segment(raw.decode(),node)
same=['Refused','need','sha','encode','remaining','on_signal','critical','load_definition_module']
for name in same:assert segment(source,tree,name)==segment(before,prior,name),name
assert "report['publishedCandidateSha256']" in source.decode()
assert "report['candidateReceiptSha256']" not in source.decode()
print(json.dumps({'schema':'heptabao.mac-complete-append-source-check.r1','ok':True,
 'sourceBytes':len(source),'sourceSha256':hashlib.sha256(source).hexdigest(),
 'preservedDefinitionsExact':same,'pythonAstOnly':True,'sourceExecuted':False,
 'hostContacted':False,'sourceCount':18,'pythonSourceCount':14,'hashOnlyJavascriptCount':4,
 'preservedSources':6,'newFiles':15,'newDirectories':['proofs'],
 'innerSeconds':45,'outerSecondsProposed':60},sort_keys=True))
